namespace EnglishCenter.Api.Infrastructure.Classes;
using System.Text.Json;
using System.Text.Json.Nodes;
using EnglishCenter.Api.Common.Errors;
using EnglishCenter.Api.Common.Validation;
using EnglishCenter.Api.Services.Academics;
using EnglishCenter.Api.Services.Classes;
using Microsoft.EntityFrameworkCore;
public sealed record ClassContactFilter(string? Name,string? Email,string? Phone,int? Course,int? Band,int Page,int Size,string Sort)
{
    public static ClassContactFilter Parse(string json,bool candidates)
    {using var doc=JsonDocument.Parse(json);var e=doc.RootElement;var allowed=new[]{"name","email","phone","page","pageSize","sort"}.Concat(candidates?new[]{"courseId","bandId"}:Array.Empty<string>()).ToArray();if(e.ValueKind!=JsonValueKind.Object||e.EnumerateObject().Any(x=>!allowed.Contains(x.Name))||e.EnumerateObject().GroupBy(x=>x.Name).Any(x=>x.Count()>1))throw ApiErrorException.Validation();
        string? Text(string k,int max){if(!e.TryGetProperty(k,out var v))return null;if(v.ValueKind!=JsonValueKind.String)throw ApiErrorException.Validation(k);try{return NonsecretText.NormalizeOptional(v.GetString(),max);}catch(ArgumentException){throw ApiErrorException.Validation(k);}}
        int Num(string k,int fallback,int max){if(!e.TryGetProperty(k,out var v))return fallback;try{return EnglishCenter.Api.Common.Serialization.StrictScalars.ParseInt32(v,1,max);}catch(ArgumentException){throw ApiErrorException.Validation(k);}}
        var email=Text("email",254);if(email?.Any(c=>c>127)==true)throw ApiErrorException.Validation("email");var phone=Text("phone",30);try{if(phone is not null)phone=ContactNormalizer.NormalizePhone(phone);}catch(ArgumentException){throw ApiErrorException.Validation("phone");}var sort=Text("sort",20)??(candidates?"ADMITTED_ASC":"ASSIGNED_ASC");if(!(candidates?new[]{"ADMITTED_ASC","ADMITTED_DESC"}:new[]{"ASSIGNED_ASC","ASSIGNED_DESC"}).Contains(sort))throw ApiErrorException.Validation("sort");return new(Text("name",100),email,phone,e.TryGetProperty("courseId",out _)?Num("courseId",1,int.MaxValue):null,e.TryGetProperty("bandId",out _)?Num("bandId",1,int.MaxValue):null,Num("page",1,int.MaxValue),Num("pageSize",20,100),sort);}
}
public static class SqlClassReads
{
    public static async Task<JsonObject> ClassPage(EnglishCenterDbContext db,IQueryCollection query,string role,int actor,CancellationToken ct)
    {
        var q=new AcademicQuery(query,role=="AcademicAffairs"?["classCode","courseId","bandId","programId","teacherId","status","sort","page","pageSize"]:role=="Teacher"?["status","courseId","sort","page","pageSize"]:["view","courseId","sort","page","pageSize"]);var page=q.Number("page");var size=q.Number("pageSize",20,100);var course=q.Id("courseId");var sort=q.Choice("sort",role=="Student"?"ASSIGNED_DESC":"CODE_ASC",role=="Student"?["ASSIGNED_ASC","ASSIGNED_DESC"]:["CODE_ASC","CODE_DESC"]);
        var rows=db.Classes.AsNoTracking();if(course is { } cid)rows=rows.Where(x=>x.Program!.CourseId==cid);
        if(role=="Teacher")rows=rows.Where(x=>x.TeacherId==actor);
        if(role=="Student") {rows=rows.Where(x=>db.StudentClassAssignments.Any(a=>a.ClassId==x.ClassId&&a.Registration!.Student!.AccountId==actor));var view=q.Choice("view","current","current","history");rows=view=="current"?rows.Where(x=>x.Status=="PLANNED"||x.Status=="OPEN"||x.Status=="ONGOING"):rows.Where(x=>x.Status=="COMPLETED"||x.Status=="CANCELLED");}
        else {var status=q.Get("status");if(status is not null){q.Choice("status","PLANNED","PLANNED","OPEN","ONGOING","COMPLETED","CANCELLED");rows=rows.Where(x=>x.Status==status);}}
        if(role=="AcademicAffairs"){var code=q.Get("classCode");if(code is not null){code=ClassWire.Code(code);rows=rows.Where(x=>x.ClassCode==code);}var band=q.Id("bandId");var program=q.Id("programId");var teacher=q.Id("teacherId");if(band is { } bid)rows=rows.Where(x=>x.Program!.BandId==bid);if(program is { } pid)rows=rows.Where(x=>x.ProgramId==pid);if(teacher is { } tid)rows=rows.Where(x=>x.TeacherId==tid);}
        var count=await rows.LongCountAsync(ct);var ordered=sort=="CODE_DESC"?rows.OrderByDescending(x=>x.ClassCode).ThenByDescending(x=>x.ClassId):sort=="ASSIGNED_ASC"?rows.OrderBy(x=>db.StudentClassAssignments.Where(a=>a.ClassId==x.ClassId&&a.Registration!.Student!.AccountId==actor).Select(a=>a.AssignedAt).First()).ThenBy(x=>db.StudentClassAssignments.Where(a=>a.ClassId==x.ClassId&&a.Registration!.Student!.AccountId==actor).Select(a=>a.ClassAssignmentId).First()):sort=="ASSIGNED_DESC"?rows.OrderByDescending(x=>db.StudentClassAssignments.Where(a=>a.ClassId==x.ClassId&&a.Registration!.Student!.AccountId==actor).Select(a=>a.AssignedAt).First()).ThenByDescending(x=>db.StudentClassAssignments.Where(a=>a.ClassId==x.ClassId&&a.Registration!.Student!.AccountId==actor).Select(a=>a.ClassAssignmentId).First()):rows.OrderBy(x=>x.ClassCode).ThenBy(x=>x.ClassId);
        var offset=(long)(page-1)*size;var data=offset>int.MaxValue?[]:await ordered.Include(x=>x.Program!).ThenInclude(x=>x.Course).Include(x=>x.Program!).ThenInclude(x=>x.Band).Include(x=>x.Teacher).Skip((int)offset).Take(size).ToArrayAsync(ct);var ids=data.Select(x=>x.ClassId).ToArray();var members=await db.StudentClassAssignments.AsNoTracking().Where(x=>ids.Contains(x.ClassId)).Include(x=>x.Registration!).ThenInclude(x=>x.Student).ToArrayAsync(ct);
        var items=data.Select(x=>{var a=members.Where(y=>y.ClassId==x.ClassId).ToArray();var s=new ClassState(x,new(x.Program!,x.Program!.Course!,x.Program!.Band!,[],true),x.Teacher!,true,a,[],0,false);var item=ClassWire.Summary(s);if(role=="Teacher")item.Remove("version");if(role=="Student"){foreach(var key in new[]{"maxSize","placedCount","createdAt","version"})item.Remove(key);item["teacher"]=new JsonObject{["displayName"]=x.Teacher!.FullName};var own=a.Single(y=>y.Registration!.Student!.AccountId==actor);item["assignment"]=ClassWire.Object(new{classAssignmentId=own.ClassAssignmentId,registrationId=own.RegistrationId,assignedAt=ClassWire.At(own.AssignedAt)});}return item;}).ToArray();return Page(items,page,size,count);
    }
    public static JsonObject Page(IEnumerable<JsonObject> items,int page,int size,long count)=>ClassWire.Object(new{items,page,pageSize=size,totalCount=count});
    public static IQueryable<PlacementSource> Candidates(EnglishCenterDbContext db)=>from r in db.Registrations.AsNoTracking() join b in db.BandAssignments on r.RegistrationId equals b.RegistrationId join i in db.Invoices on r.RegistrationId equals i.RegistrationId join profile in db.StudentProfiles on r.StudentId equals profile.StudentId join a in db.Accounts on profile.AccountId equals a.AccountId join c in db.Courses on r.CourseId equals c.CourseId join band in db.Bands on b.BandId equals band.BandId join best in db.EntryTestAttempts on b.BestAttemptId equals best.AttemptId where r.Status=="ADMITTED"&&i.Status=="PAID"&&!db.StudentClassAssignments.Any(x=>x.RegistrationId==r.RegistrationId) select new PlacementSource{Registration=r,BandAssignment=b,Invoice=i,Student=a,Course=c,Band=band,Best=best};
    public static async Task<JsonObject> CandidatePage(EnglishCenterDbContext db,ClassContactFilter f,CancellationToken ct)
    {var q=Candidates(db);if(f.Name is { } n)q=q.Where(x=>x.Student.FullName.Contains(n));if(f.Email is { } e)q=q.Where(x=>x.Student.Email.Contains(e));if(f.Phone is { } p)q=q.Where(x=>x.Student.Phone==p);if(f.Course is { } c)q=q.Where(x=>x.Registration.CourseId==c);if(f.Band is { } b)q=q.Where(x=>x.BandAssignment.BandId==b);var count=await q.LongCountAsync(ct);var sorted=f.Sort=="ADMITTED_DESC"?q.OrderByDescending(x=>x.Registration.AdmissionApprovedAt).ThenByDescending(x=>x.Registration.RegistrationId):q.OrderBy(x=>x.Registration.AdmissionApprovedAt).ThenBy(x=>x.Registration.RegistrationId);var offset=(long)(f.Page-1)*f.Size;var data=offset>int.MaxValue?[]:await sorted.Skip((int)offset).Take(f.Size).ToArrayAsync(ct);return Page(data.Select(x=>ClassPreviews.Candidate(x,false)),f.Page,f.Size,count);}
    public static async Task<JsonObject> Roster(EnglishCenterDbContext db,int id,ClassContactFilter f,bool teacher,CancellationToken ct)
    {
        var q=from a in db.StudentClassAssignments.AsNoTracking() join r in db.Registrations on a.RegistrationId equals r.RegistrationId join s in db.StudentProfiles on r.StudentId equals s.StudentId join account in db.Accounts on s.AccountId equals account.AccountId where a.ClassId==id select new{Assignment=a,Registration=r,Student=account};if(f.Name is { } n)q=q.Where(x=>x.Student.FullName.Contains(n));if(f.Email is { } e)q=q.Where(x=>x.Student.Email.Contains(e));if(f.Phone is { } p)q=q.Where(x=>x.Student.Phone==p);var count=await q.LongCountAsync(ct);var sorted=f.Sort=="ASSIGNED_DESC"?q.OrderByDescending(x=>x.Assignment.AssignedAt).ThenByDescending(x=>x.Assignment.ClassAssignmentId):q.OrderBy(x=>x.Assignment.AssignedAt).ThenBy(x=>x.Assignment.ClassAssignmentId);var offset=(long)(f.Page-1)*f.Size;var data=offset>int.MaxValue?[]:await sorted.Skip((int)offset).Take(f.Size).ToArrayAsync(ct);var ids=data.Select(x=>x.Registration.RegistrationId).ToArray();var sources=await (from r in db.Registrations.AsNoTracking() join b in db.BandAssignments on r.RegistrationId equals b.RegistrationId join i in db.Invoices on r.RegistrationId equals i.RegistrationId join c in db.Courses on r.CourseId equals c.CourseId join band in db.Bands on b.BandId equals band.BandId join best in db.EntryTestAttempts on b.BestAttemptId equals best.AttemptId where !teacher&&ids.Contains(r.RegistrationId) select new{Id=r.RegistrationId,Course=c,Band=band,Best=best,InvoiceStatus=i.Status}).ToDictionaryAsync(x=>x.Id,ct);
        return Page(data.Select(x=>{var row=ClassWire.Object(new{classAssignmentId=x.Assignment.ClassAssignmentId,registrationId=x.Registration.RegistrationId,assignedAt=ClassWire.At(x.Assignment.AssignedAt),student=new{studentId=x.Registration.StudentId,fullName=x.Student.FullName,email=x.Student.Email,phone=x.Student.Phone}});if(!teacher){var s=sources[x.Registration.RegistrationId];row["course"]=ClassWire.Object(new{id=s.Course.CourseId,code=s.Course.CourseCode,name=s.Course.CourseName,status=s.Course.Status});row["band"]=ClassWire.Object(new{id=s.Band.BandId,code=s.Band.BandCode,minScore=EnglishCenter.Api.Common.Serialization.ExactNumbers.FormatScore(s.Band.MinScore)});row["entryScore"]=EnglishCenter.Api.Common.Serialization.ExactNumbers.FormatScore(s.Best.Score!.Value);row["invoiceStatus"]=s.InvoiceStatus;}return row;}),f.Page,f.Size,count);
    }
    public static JsonObject ScheduleView(ClassState s,EnglishCenter.Api.Domain.Training.Schedule row)
    {var next=s.Schedules.SingleOrDefault(x=>x.ReplacesScheduleId==row.ScheduleId);var terminal=s.Schedules.Single(x=>x.ObligationKey==row.ObligationKey&&x.IsCurrent);var w=ClassWire.Window(row);return ClassWire.Object(new{id=row.ScheduleId,@class=new{id=s.Class.ClassId,code=s.Class.ClassCode,status=s.Class.Status,program=ClassWire.Program(s.Program),teacher=ClassWire.Teacher(s.Teacher)},type=row.SessionType,date=row.SessionDate.ToString("yyyy-MM-dd"),startTime=row.StartTime.ToString("HH:mm"),endTime=row.EndTime.ToString("HH:mm"),startAt=ClassWire.At(w.StartAt),endAt=ClassWire.At(w.EndAt),room=row.Room,occurrenceState=row.OccurrenceState,isCurrent=row.IsCurrent,obligationKey=row.ObligationKey,replacesScheduleId=row.ReplacesScheduleId,replacementScheduleId=next?.ScheduleId,currentScheduleId=terminal.ScheduleId,version=ClassWire.Rv(row.RowVersion)});}
    public static async Task<JsonObject> ScheduleDetail(EnglishCenterDbContext db,int id,DateTime now,CancellationToken ct)
    {var row=await db.Schedules.AsNoTracking().SingleOrDefaultAsync(x=>x.ScheduleId==id,ct)??throw new ApiErrorException(ApiErrorCode.NOT_FOUND);var s=await SqlClassRepository.ReadState(db,row.ClassId,ct);var detail=ScheduleView(s,row);detail["held"]=row.HeldAt is { } h?ClassWire.Object(new{actorAccountId=row.HeldBy,at=ClassWire.At(h)}):null;detail["notHeld"]=row.NotHeldAt is { } n?ClassWire.Object(new{actorAccountId=row.NotHeldBy,at=ClassWire.At(n),reason=row.NotHeldReason}):null;var chain=s.Schedules.Where(x=>x.ObligationKey==row.ObligationKey).ToList();var ordered=new List<JsonNode>();int? predecessor=null;while(chain.Count>0){var link=chain.SingleOrDefault(x=>x.ReplacesScheduleId==predecessor)??throw new ApiErrorException(ApiErrorCode.INTERNAL_ERROR);ordered.Add(ClassWire.Object(new{scheduleId=link.ScheduleId,replacesScheduleId=link.ReplacesScheduleId,date=link.SessionDate.ToString("yyyy-MM-dd"),startTime=link.StartTime.ToString("HH:mm"),endTime=link.EndTime.ToString("HH:mm"),occurrenceState=link.OccurrenceState,isCurrent=link.IsCurrent}));predecessor=link.ScheduleId;chain.Remove(link);}detail["replacementChain"]=ClassWire.Array(ordered);var attendance=await db.Attendances.AnyAsync(x=>x.ScheduleId==id,ct);var score=await db.Scores.AnyAsync(x=>x.ScheduleId==id,ct);detail["dependencies"]=ClassWire.Object(new{hasAttendance=attendance,hasLinkedScore=score});SchedulePreviews.DetailActions(detail,s,row,now,attendance,score);return detail;}
}
